import BlockchainManager from './blockchain.js';

let currentScreen = 'auth';
let blockchainManager = null;
let playerData = null;
let isWalletConnected = false;

const screens = {
    auth: document.getElementById('authScreen'),
    mainMenu: document.getElementById('mainMenuScreen'),
    game: document.getElementById('gameScreen'),
    gameOver: document.getElementById('gameOverScreen'),
    profile: document.getElementById('profileScreen'),
    leaderboard: document.getElementById('leaderboardScreen'),
    loading: document.getElementById('loadingScreen')
};

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const dinoImg = new Image();
dinoImg.src = 'img/dino.png';
const dinoRun1Img = new Image();
dinoRun1Img.src = 'img/dinorun.png';
const dinoRun2Img = new Image();
dinoRun2Img.src = 'img/dinorun1.png';
const dinoRun3Img = new Image();
dinoRun3Img.src = 'img/dinorun2.png';
const dinoSit1Img = new Image();
dinoSit1Img.src = 'img/dinoduck.png';
const dinoSit2Img = new Image();
dinoSit2Img.src = 'img/dinoduck1.png';
const dinoSit3Img = new Image();
dinoSit3Img.src = 'img/dinoduck2.png';
const dinoJumpImg = new Image();
dinoJumpImg.src = 'img/dinoJump.png';

const cactus1Img = new Image();
cactus1Img.src = 'img/cactusBig.png';
const cactus2Img = new Image();
cactus2Img.src = 'img/cactusSmall.png';
const cactusSmallManyImg = new Image();
cactusSmallManyImg.src = 'img/cactusSmallMany.png';

const bird1 = new Image();
bird1.src = 'img/bird.png';
const bird2 = new Image();
bird2.src = 'img/bird2.png';

const groundImg = new Image();
groundImg.src = 'img/ground.png';
const cloudImg = new Image();
cloudImg.src = 'img/cloud.png';


const heightJump = -14;
const gravityValue = 0.6;
const startGameSpeed = 5;
const groundForDino = 275;
const generationInterval = 1500;
const minGenerationInterval = 500;
const probabilityOfObjectAppearance = 0.02;

let dino = {
  x: 50,
  y: groundForDino,
  defaultWidth: 50,
  defaultHeight: 65,
  duckWidth: 27,
  duckHeight: 35,
  vy: 0,
  gravity: gravityValue,
  jumpPower: heightJump,
  isJumping: false,
  isDucking: false
};
let obstacles = [];
let ground = [
  { x: 0, y: 320 },
  { x: 800, y: 320 }
];
let clouds = [
  { x: 400, y: 60 },
  { x: 150, y: 80 },
  { x: 650, y: 110 }
];
let score = 0;
let gameOver = false;
let gameStarted = false;
let gameSpeed = startGameSpeed;
let lastObstacleTime = 0;
let frameCounter = 0;
let currentDinoFrame = 0;

let lastTime = performance.now();
const targetFrameTime = 1000 / 60;
let isTabVisible = true;

function update() {
  if (!gameStarted) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ground.forEach(g => {
      ctx.drawImage(groundImg, g.x, g.y, 800, 80);
    });
    clouds.forEach(cloud => {
      ctx.drawImage(cloudImg, cloud.x, cloud.y, 50, 30);
    });
    
    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = 'high';
    ctx.drawImage(dinoImg, dino.x, dino.y, dino.defaultWidth, dino.defaultHeight);
    return;
  }

  // Приостанавливаем игру если вкладка неактивна
  if (!isTabVisible) {
    requestAnimationFrame(update);
    return;
  }

  const currentTime = performance.now();
  const deltaTime = (currentTime - lastTime) / targetFrameTime;
  lastTime = currentTime;

  if (!gameOver) {
    dino.vy += dino.gravity * deltaTime;
    dino.y += dino.vy * deltaTime;
    if (dino.y > groundForDino) {
      dino.y = groundForDino;
      dino.vy = 0;
      dino.isJumping = false;
    }
    
    if (dino.isDucking && !dino.isJumping) {
      dino.width = dino.duckWidth;
      dino.height = dino.duckHeight;
      dino.y = groundForDino + (dino.defaultHeight - dino.duckHeight);
    } else {
      dino.width = dino.defaultWidth;
      dino.height = dino.defaultHeight;
    }

    obstacles.forEach(obstacle => {
      obstacle.x -= gameSpeed * deltaTime;
    });
    obstacles = obstacles.filter(ob => ob.x > -ob.width);

    score += 0.1 * deltaTime;

    gameSpeed = startGameSpeed + Math.floor(score / 20) * 0.5;
    dino.gravity = gravityValue + Math.floor(score / 20) * 0.05;
    dino.jumpPower = heightJump + Math.floor(score / 20) * -0.22;
    let currentGenerationInterval = Math.max(minGenerationInterval, generationInterval - Math.floor(score / 20) * 20);

    if (Date.now() - lastObstacleTime > currentGenerationInterval && Math.random() < probabilityOfObjectAppearance) {
      const rand = Math.random();
      let newObstacle;
      if (rand < 0.15) {
        newObstacle = {
          x: 800,
          y: groundForDino - 27 - Math.random() * 100,
          width: 65,
          height: 65,
          type: 'bird'
        };
      } else if (rand < 0.33) {
        newObstacle = {
          x: 800,
          y: groundForDino - 60 + dino.defaultHeight,
          width: 30,
          height: 60,
          type: 'cactusBig'
        };
      } else if (rand < 0.66) {
        newObstacle = {
          x: 800,
          y: groundForDino - 33 + dino.defaultHeight,
          width: 30,
          height: 33,
          type: 'cactusSmall'
        };
      } else {
        newObstacle = {
          x: 800,
          y: groundForDino - 40 + dino.defaultHeight,
          width: 70,
          height: 40,
          type: 'cactusSmallMany'
        };
      }
      obstacles.push(newObstacle);
      lastObstacleTime = Date.now();
            }

    ground.forEach(g => {
      g.x -= gameSpeed * deltaTime;
      if (g.x <= -800) g.x += 1600;
    });

    clouds.forEach(cloud => {
      cloud.x -= (gameSpeed / 2) * deltaTime;
      if (cloud.x <= -50) cloud.x += 900;
    });

    frameCounter += deltaTime;
    if (!dino.isJumping && gameStarted) {
      // Более стабильная анимация (бег и присед)
      const animationSpeed = 0.1; // Скорость смены кадров
      if (Math.floor(frameCounter * animationSpeed) % 3 === 0) {
        currentDinoFrame = 0;
      } else if (Math.floor(frameCounter * animationSpeed) % 3 === 1) {
        currentDinoFrame = 1;
      } else {
        currentDinoFrame = 2;
      }
    }

    obstacles.forEach(ob => {
        // Уменьшенные зоны столкновения для более справедливого геймплея
        const collisionMargin = 8; // Отступ от краев препятствия
        const obCollisionWidth = Math.max(ob.width - collisionMargin * 2, ob.width * 0.6);
        const obCollisionHeight = Math.max(ob.height - collisionMargin * 2, ob.height * 0.7);
        const obCollisionX = ob.x + (ob.width - obCollisionWidth) / 2;
        const obCollisionY = ob.y + (ob.height - obCollisionHeight) / 2;
        
        // Также уменьшаем зону столкновения динозавра
        const dinoCollisionMargin = 5;
        const dinoCollisionWidth = dino.width - dinoCollisionMargin * 2;
        const dinoCollisionHeight = dino.height - dinoCollisionMargin * 2;
        const dinoCollisionX = dino.x + dinoCollisionMargin;
        const dinoCollisionY = dino.y + dinoCollisionMargin;
        
        if (
          dinoCollisionX < obCollisionX + obCollisionWidth &&
          dinoCollisionX + dinoCollisionWidth > obCollisionX &&
          dinoCollisionY < obCollisionY + obCollisionHeight &&
          dinoCollisionY + dinoCollisionHeight > obCollisionY
        ) {
        
            showGameOver();
      }
    });
  }

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ground.forEach(g => {
    ctx.drawImage(groundImg, g.x, g.y, 800, 80);
  });

  clouds.forEach(cloud => {
    ctx.drawImage(cloudImg, cloud.x, cloud.y, 50, 30);
  });

  let currentDinoImg;
  if (dino.isJumping) {
    currentDinoImg = dinoJumpImg;
  } else if (dino.isDucking) {
    // Анимация приседания с 3 кадрами
    if (currentDinoFrame === 0) {
      currentDinoImg = dinoSit1Img;
    } else if (currentDinoFrame === 1) {
      currentDinoImg = dinoSit2Img;
    } else {
      currentDinoImg = dinoSit3Img;
        }
  } else {
    // Анимация бега с 3 кадрами
    if (currentDinoFrame === 0) {
      currentDinoImg = dinoRun1Img;
    } else if (currentDinoFrame === 1) {
      currentDinoImg = dinoRun2Img;
    } else {
      currentDinoImg = dinoRun3Img;
    }
  }
  
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';
  ctx.drawImage(currentDinoImg, dino.x, dino.y, dino.width, dino.height);

  obstacles.forEach(ob => {
    let obstacleImg;
    if (ob.type === 'bird') {
      obstacleImg = Math.floor(frameCounter) % 20 < 10 ? bird1 : bird2;
    } else if (ob.type === 'cactusBig') {
      obstacleImg = cactus1Img;
    } else if (ob.type === 'cactusSmall') {
      obstacleImg = cactus2Img;
    } else {
      obstacleImg = cactusSmallManyImg;
    }
    ctx.drawImage(obstacleImg, ob.x, ob.y, ob.width, ob.height);
  });

  ctx.font = 'bold 28px "Roboto Condensed", sans-serif';
  ctx.textAlign = 'center';

  const scoreGradient = ctx.createLinearGradient(400, 0, 400, 40);
  scoreGradient.addColorStop(0, '#FF4444');
  scoreGradient.addColorStop(0.5, '#FF6666');
  scoreGradient.addColorStop(1, '#FF8888');

  ctx.shadowColor = 'transparent';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;

  ctx.fillStyle = scoreGradient;
  ctx.fillText(`Score: ${Math.floor(score)}`, 400, 40);

  ctx.shadowColor = 'transparent';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;

  if (gameOver) {
    ctx.save();
    ctx.font = '40px "Impact", sans-serif';
    ctx.textAlign = 'center';
    const gameOverGradient = ctx.createLinearGradient(300, 150, 300, 200);
    gameOverGradient.addColorStop(0, '#FF0000');
    gameOverGradient.addColorStop(1, '#8B0000');
    ctx.shadowColor = 'rgba(0, 0, 0, 0.7)';
    ctx.shadowBlur = 8;
    ctx.shadowOffsetX = 4;
    ctx.shadowOffsetY = 4;
    ctx.fillStyle = gameOverGradient;
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 1;
    ctx.fillText('Game Over', 400, 180);
    ctx.strokeText('Game Over', 400, 180);
    ctx.restore();
  }

  ctx.textAlign = 'start';

  if (gameStarted) {
    requestAnimationFrame(update);
        }
    }
    
function startGame() {
  dino.y = groundForDino;
  dino.vy = 0;
  dino.isJumping = false;
  dino.isDucking = false;
  obstacles = [];
  score = 0;
  gameOver = false;
  gameSpeed = startGameSpeed;
  lastObstacleTime = Date.now();
  frameCounter = 0;
  currentDinoFrame = 0; // Гарантируем начальный кадр анимации
  
  // Принудительно сбрасываем анимацию
  dino.gravity = gravityValue;
  dino.jumpPower = heightJump;
  
  gameStarted = true;
  lastTime = performance.now();
  requestAnimationFrame(update);
    }
    

document.addEventListener('keydown', (e) => {
  if ((e.code === 'Space' || e.code === 'ArrowUp') && !gameOver && !dino.isJumping && gameStarted) {
    dino.vy = dino.jumpPower;
    dino.isJumping = true;
    dino.isDucking = false;
  } else if (e.code === 'ArrowDown' && !gameOver && !dino.isJumping && gameStarted) {
    dino.isDucking = true;
    }
});

document.addEventListener('keyup', (e) => {
  if (e.code === 'ArrowDown' && !gameOver && gameStarted) {
    dino.isDucking = false;
  }
});

function showScreen(screenName) {
    Object.values(screens).forEach(screen => {
        screen.classList.add('hidden');
    });
    
    if (screens[screenName]) {
        screens[screenName].classList.remove('hidden');
        currentScreen = screenName;
        
        if (screenName === 'game') {
            startGame();
        }
        
        // Обновляем статус Magic Block при показе главного меню
        if (screenName === 'mainMenu') {
            updateMagicBlockStatus();
        }
    }
}

function showLoading() {
    showScreen('loading');
}

function hideLoading() {
    if (currentScreen === 'loading') {
        showScreen('mainMenu');
    }
}

async function checkExistingPlayer() {
    try {
        
        playerData = await blockchainManager.getPlayerData();
        
        if (playerData && playerData.username) {
            
            document.getElementById('playerName').textContent = playerData.username;
            document.getElementById('currentUsername').textContent = playerData.username;
            
            const usernameForm = document.getElementById('usernameForm');
            usernameForm.innerHTML = `
                <h3>Welcome back, ${playerData.username}!</h3>
                <button id="continueBtn" class="register-btn">
                    <span class="shadow"></span>
                    <span class="edge"></span>
                    <span class="front text">Continue to Game</span>
                </button>
            `;
            usernameForm.style.display = 'block';
            
            document.getElementById('continueBtn').addEventListener('click', async () => {
                showScreen('mainMenu');
                // Автоматически включаем Fast Mode
                await autoEnableFastMode();
            });
            
        } else {
            
            const usernameForm = document.getElementById('usernameForm');
            usernameForm.innerHTML = `
                <h3>Choose your username:</h3>
                <input type="text" id="usernameInput" placeholder="Enter username" maxlength="32">
                <button id="registerBtn" class="register-btn">
                    <span class="shadow"></span>
                    <span class="edge"></span>
                    <span class="front text">Register & Play</span>
                </button>
            `;
            usernameForm.style.display = 'block';
            
            document.getElementById('registerBtn').addEventListener('click', registerPlayer);
            document.getElementById('usernameInput').addEventListener('keypress', (e) => {
                if (e.key === 'Enter') {
                    registerPlayer();
                }
            });
        }
        
    } catch (error) {
        
        const usernameForm = document.getElementById('usernameForm');
        usernameForm.innerHTML = `
            <h3>Choose your username:</h3>
            <input type="text" id="usernameInput" placeholder="Enter username" maxlength="32">
            <button id="registerBtn" class="register-btn">
                <span class="shadow"></span>
                <span class="edge"></span>
                <span class="front text">Register & Play</span>
            </button>
        `;
        usernameForm.style.display = 'block';
        
        document.getElementById('registerBtn').addEventListener('click', registerPlayer);
        document.getElementById('usernameInput').addEventListener('keypress', (e) => {
            if (e.key === 'Enter') {
                registerPlayer();
            }
        });
    }
}

async function initializeBlockchain() {
    try {
        blockchainManager = new BlockchainManager();
        const success = await blockchainManager.initialize();
        
        if (success) {
            isWalletConnected = true;
            
            showScreen('auth');
            
            await checkExistingPlayer();
            
            const connectBtn = document.getElementById('connectWalletBtn');
            connectBtn.innerHTML = `
                <span class="shadow"></span>
                <span class="edge"></span>
                <span class="front text">Wallet Connected ✓</span>
            `;
            connectBtn.classList.add('connected');
        } else {
            throw new Error('Failed to initialize blockchain');
        }
    } catch (error) {
        alert('Failed to connect to blockchain. Please try again.');
    }
}

let isRegistering = false;

async function registerPlayer() {
    if (isRegistering) {
        return;
    }
    
    const username = document.getElementById('usernameInput').value.trim();
    
    if (!username) {
        alert('Please enter a username');
        return;
    }
    
    if (username.length > 32) {
        alert('Username must be 32 characters or less');
        return;
    }
    
    try {
        isRegistering = true;
        showLoading();
        
        try {
            await blockchainManager.initializeGameState();
        } catch (error) {
        }
        
        const result = await blockchainManager.registerPlayer(username);
        
        playerData = await blockchainManager.getPlayerData();
        
        document.getElementById('playerName').textContent = username;
        document.getElementById('currentUsername').textContent = username;
        
        hideLoading();
        
        if (result === 'duplicate_transaction_success') {
            alert('Player was already registered!');
        } else {
            alert('Player registered successfully!');
        }
        
        showScreen('mainMenu');
        
        // Автоматически включаем Fast Mode после регистрации
        await autoEnableFastMode();
        
    } catch (error) {
        hideLoading();
        
        if (error.message && error.message.includes('already taken')) {
            alert(error.message);
        } else if (error.message && error.message.includes('already been processed')) {
            alert('Player might already be registered. Please refresh and try again.');
        } else {
            alert('Failed to register player. Please try again.');
        }
        
        showScreen('auth');
    } finally {
        isRegistering = false;
    }
}


let isSubmittingScore = false;

async function submitScoreToBlockchain(score) {
    if (isSubmittingScore) {
        return;
    }
    
    const submitBtn = document.getElementById('submitScoreBtn');
    
    try {
        isSubmittingScore = true;
        
        if (submitBtn) {
            submitBtn.disabled = true;
            submitBtn.innerHTML = `
                <span class="shadow"></span>
                <span class="edge"></span>
                <span class="front text">Submitting...</span>
            `;
        }
        
        showLoading();
        
        const result = await blockchainManager.submitScore(score);
        
        playerData = await blockchainManager.getPlayerData();
        
        hideLoading();
        
        // Успешно!
        
        // Автоматически возвращаемся в меню
        showScreen('mainMenu');
        
    } catch (error) {
        hideLoading();
        
        if (error.message && error.message.includes('already been processed')) {
            try {
                const currentPlayerData = await blockchainManager.getPlayerData();
                if (currentPlayerData && currentPlayerData.bestScore) {
                    const currentBestScore = currentPlayerData.bestScore.toNumber();
                    if (currentBestScore >= score) {
                        showScreen('mainMenu');
                        return;
                    }
                }
            } catch (verifyError) {
                console.error('Verification error:', verifyError);
            }
        }
        
        // Показываем ошибку только если реально не прошло
        alert('Failed to submit score. Please try again.');
        console.error('Submit score error:', error);
    } finally {
        isSubmittingScore = false;
        
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = `
                <span class="shadow"></span>
                <span class="edge"></span>
                <span class="front text">Submit Score</span>
            `;
        }
        }
    }
    
async function loadPlayerProfile() {
        try {
        if (blockchainManager && isWalletConnected) {
            playerData = await blockchainManager.getPlayerData();
            
            if (playerData) {
                document.getElementById('currentUsername').textContent = playerData.username;
                document.getElementById('gamesPlayed').textContent = playerData.gamesPlayed.toString();
                document.getElementById('bestScore').textContent = playerData.bestScore.toString();
                document.getElementById('totalScore').textContent = playerData.totalScore.toString();
            }
            }
        } catch (error) {
        }
    }
    
async function loadLeaderboard() {
        try {
        if (blockchainManager && isWalletConnected) {
            
            const leaderboardData = await blockchainManager.getLeaderboard();
            
            
            document.getElementById('totalPlayers').textContent = leaderboardData.totalPlayers;
            document.getElementById('totalGames').textContent = leaderboardData.totalGames;
            
            const leaderboardList = document.getElementById('leaderboardList');
            
            if (leaderboardData.players && leaderboardData.players.length > 0) {
                
                leaderboardList.innerHTML = leaderboardData.players.map((player, index) => {
                    const isCurrentPlayer = player.authority === blockchainManager.wallet.publicKey.toString();
                    return `
                        <div class="leaderboard-entry ${isCurrentPlayer ? 'current-player' : 'clickable'}" ${isCurrentPlayer ? 'title="This is you! Click to view game history"' : 'title="Click to view game history"'} data-player-name="${player.name}">
                        <div class="rank-col">${index + 1}</div>
                            <div class="name-col" title="${player.name}">${player.name}</div>
                            <div class="games-col">${player.gamesPlayed}</div>
                            <div class="score-col">${player.bestScore.toLocaleString()}</div>
                            <div class="date-col">${formatDate(player.bestScoreTimestamp)}</div>
                        </div>
                    `;
                }).join('');

                leaderboardList.querySelectorAll('.leaderboard-entry.clickable, .leaderboard-entry.current-player').forEach(entry => {
                    entry.addEventListener('click', () => {
                        const playerName = entry.getAttribute('data-player-name');
                        showPlayerHistory(playerName);
                    });
                });
            } else {
                leaderboardList.innerHTML = '<div class="loading">No players found. Be the first to play!</div>';
            }
        } else {
            document.getElementById('leaderboardList').innerHTML = '<div class="loading">Please connect your wallet first</div>';
            }
        } catch (error) {
        document.getElementById('leaderboardList').innerHTML = '<div class="loading">Failed to load leaderboard. Please try again.</div>';
    }
}

function formatDate(timestamp) {
    if (!timestamp || timestamp === 0) return 'Never';
    
    try {
        const date = new Date(timestamp * 1000); // Convert from Unix timestamp
        return date.toLocaleDateString('en-US') + ' ' + date.toLocaleTimeString('en-US', {hour: '2-digit', minute: '2-digit'});
    } catch (error) {
        return 'Unknown';
    }
}

function showPlayerHistory(playerName) {
    if (playerName && blockchainManager && isWalletConnected) {
        const currentPlayerData = playerData;
        if (currentPlayerData && currentPlayerData.username === playerName) {
            showCurrentPlayerHistory();
        } else {
            alert(`Game history for player "${playerName}" is not available. Only your own game history is shown.`);
        }
    } else {
        showCurrentPlayerHistory();
    }
}

async function showCurrentPlayerHistory() {
    try {
        const gameHistory = await blockchainManager.getGameHistory();
        
        if (gameHistory.length === 0) {
            alert('You have no game history yet. Play some games!');
            return;
        }

    const modal = document.createElement('div');
    modal.className = 'game-history-modal';
    modal.innerHTML = `
        <div class="game-history-content">
                    <div class="game-history-header">
                <h3>Your Game History</h3>
                <button class="close-history-btn">&times;</button>
                    </div>
                    <div class="game-history-list">
                ${gameHistory.map((game, index) => `
                                <div class="game-history-entry">
                        <div class="game-number">#${gameHistory.length - index}</div>
                        <div class="game-score">${game.score} points</div>
                        <div class="game-date">${game.date}</div>
                                </div>
                `).join('')}
            </div>
                    </div>
                `;

    document.body.appendChild(modal);

    const closeBtn = modal.querySelector('.close-history-btn');
    closeBtn.addEventListener('click', () => {
        document.body.removeChild(modal);
    });

    modal.addEventListener('click', (e) => {
        if (e.target === modal) {
            document.body.removeChild(modal);
            }
    });
    
        } catch (error) {
        alert('Failed to load game history. Please try again later.');
        }
    }
    
document.addEventListener('DOMContentLoaded', function() {
    document.getElementById('connectWalletBtn').addEventListener('click', initializeBlockchain);
    
    document.getElementById('playGameBtn').addEventListener('click', () => showScreen('game'));
    document.getElementById('leaderboardBtn').addEventListener('click', () => {
        loadLeaderboard();
        showScreen('leaderboard');
    });
    document.getElementById('profileBtn').addEventListener('click', () => {
        loadPlayerProfile();
        showScreen('profile');
    });
    
    // Magic Block: автоматическое делегирование (кнопка больше не нужна)
    
    
    document.getElementById('restartGameBtn').addEventListener('click', () => {
        showScreen('game');
        restartGame();
    });
    document.getElementById('submitScoreBtn').addEventListener('click', () => {
        const submitBtn = document.getElementById('submitScoreBtn');
        if (isSubmittingScore) {
            return; // Ignore if already submitting
        }
        submitScoreToBlockchain(Math.floor(score));
    });
    document.getElementById('backToMenuFromGameOverBtn').addEventListener('click', () => showScreen('mainMenu'));
    
    document.getElementById('backToMenuFromProfileBtn').addEventListener('click', () => showScreen('mainMenu'));
    
    document.getElementById('backToMenuFromLeaderboardBtn').addEventListener('click', () => showScreen('mainMenu'));
    
    
    // Обработчик для приостановки игры при смене вкладки
    document.addEventListener('visibilitychange', () => {
        isTabVisible = !document.hidden;
        
        // Если вкладка стала неактивной во время игры, сбрасываем время
        if (!isTabVisible && gameStarted) {
            lastTime = performance.now();
        }
        
        // Если вкладка стала активной, также сбрасываем время для плавного возобновления
        if (isTabVisible && gameStarted) {
            lastTime = performance.now();
        }
    });
    
    // Обработчики для приостановки игры при переключении окон
    window.addEventListener('blur', () => {
        isTabVisible = false;
        if (gameStarted) {
            lastTime = performance.now();
        }
    });
    
    window.addEventListener('focus', () => {
        isTabVisible = true;
        if (gameStarted) {
            lastTime = performance.now();
        }
    });
});

function showGameOver() {
    gameOver = true;
    document.getElementById('finalScore').textContent = Math.floor(score);
    showScreen('gameOver');
}

function restartGame() {
    // Полный сброс всех игровых переменных
    gameStarted = false;
    gameOver = false;
    
    // Сбрасываем состояние динозавра
    dino.y = groundForDino;
    dino.vy = 0;
    dino.isJumping = false;
    dino.isDucking = false;
    
    // Сбрасываем игровые переменные
    obstacles = [];
    score = 0;
    gameSpeed = startGameSpeed;
    lastObstacleTime = Date.now();
    
    // КРИТИЧНО: сбрасываем анимацию
    frameCounter = 0;
    currentDinoFrame = 0;
    
    // Принудительно сбрасываем анимацию для корректного старта
    dino.gravity = gravityValue;
    dino.jumpPower = heightJump;
    
    // Сбрасываем время для корректной работы deltaTime
    lastTime = performance.now();
    
    // Запускаем новую игру
    showScreen('game');
}

// ============================================
// Magic Block: Fast Mode Management
// ============================================

async function updateMagicBlockStatus() {
    if (!blockchainManager || !isWalletConnected) {
        return;
    }
    
    try {
        const info = blockchainManager.getInfo();
        const badge = document.getElementById('magicBlockStatus');
        const label = document.getElementById('mbStatusText');
        
        if (info.delegated) {
            label.textContent = 'Instant Mode';
            badge.className = 'mb-badge fast-mode';
        } else {
            label.textContent = 'Activating...';
            badge.className = 'mb-badge standard-mode';
        }
    } catch (error) {
        console.error('Error updating Magic Block status:', error);
    }
}

/**
 * Автоматически включает Fast Mode при входе в игру
 * Вызывается после успешного подключения/регистрации
 */
async function autoEnableFastMode() {
    if (!blockchainManager || !isWalletConnected) {
        return;
    }
    
    try {
        if (blockchainManager.isDelegated) {
            await updateMagicBlockStatus();
            return;
        }
        
        const result = await blockchainManager.enableFastMode();
        
        await updateMagicBlockStatus();
        
    } catch (error) {
        console.error('Could not auto-enable Fast Mode:', error);
        await updateMagicBlockStatus();
    }
}

