import { Connection, PublicKey, SystemProgram } from '@solana/web3.js';
import { AnchorProvider, Program } from '@coral-xyz/anchor';
import BN from 'bn.js';

if (typeof window !== 'undefined') {
    window.BN = BN;
window.Buffer = Buffer;
}

class BlockchainManager {
    constructor() {
        this.l1Connection = null;
        this.erConnection = null;
        this.connection = null;
        this.l1Provider = null;
        this.erProvider = null;
        this.provider = null;
        this.l1Program = null;
        this.erProgram = null;
        this.program = null;
        this.wallet = null;
        this.playerAccount = null;
        this.gameStateAccount = null;
        this.isConnected = false;
        this.isDelegated = false;
    }
    
    async initialize() {
        try {
            const wallet = await this.getWallet();
            if (!wallet || !wallet.publicKey) {
                throw new Error('Wallet not found');
            }
            this.wallet = wallet;
            
            this.l1Connection = new Connection('https://api.devnet.solana.com', 'confirmed');
            this.erConnection = new Connection('https://devnet.magicblock.app', 'processed');
            this.connection = this.l1Connection;
            
            const phantomWallet = {
                publicKey: wallet.publicKey,
                signTransaction: async (tx) => {
                    return await (wallet.signTransaction || window.solana.signTransaction)(tx);
                },
                signAllTransactions: async (txs) => {
                    return await (wallet.signAllTransactions || window.solana.signAllTransactions)(txs);
                }
            };
            
            this.l1Provider = new AnchorProvider(this.l1Connection, phantomWallet, {
                preflightCommitment: 'confirmed',
                commitment: 'confirmed'
            });
            
            this.erProvider = new AnchorProvider(this.erConnection, phantomWallet, {
                preflightCommitment: 'processed',
                commitment: 'processed'
            });
            
            this.provider = this.l1Provider;
            
            const idl = await this.loadIDL();
            
            this.l1Program = new Program(idl, this.l1Provider);
            this.erProgram = new Program(idl, this.erProvider);
            this.program = this.l1Program;
            
            const programId = this.program.programId;
            
            this.gameStateAccount = PublicKey.findProgramAddressSync(
                [Buffer.from('game_state')],
                programId
            )[0];
            
            this.playerAccount = PublicKey.findProgramAddressSync(
                [Buffer.from('player'), wallet.publicKey.toBuffer()],
                programId
            )[0];
            
            await this.checkDelegationStatus();
            
            this.isConnected = true;
            return true;
        } catch (error) {
            console.error('Initialization error:', error);
            return false;
        }
    }

    async getWallet() {
        if (window.solana && window.solana.isPhantom) {
            try {
                const response = await window.solana.connect();
                if (!response || !response.publicKey) {
                    throw new Error('Invalid wallet response');
                }
                return response;
            } catch (error) {
                console.error('Failed to connect to Phantom:', error);
                throw new Error('Failed to connect to Phantom wallet');
            }
        }
        
        alert(`🚨 PHANTOM WALLET REQUIRED

To play this blockchain game, you need Phantom wallet:

1. Install from: https://phantom.app/
2. Create a wallet
3. Switch to Devnet in settings
4. Get test SOL from: https://faucet.solana.com/
5. Refresh and try again

After installation, click "Connect Wallet" again.`);
        throw new Error('Phantom wallet not found');
    }

    async loadIDL() {
        try {
            const response = await fetch('/js/idl.json');
            if (!response.ok) {
                throw new Error('Failed to load IDL');
            }
            const idl = await response.json();
            return idl;
        } catch (error) {
            console.error('Failed to load IDL:', error);
            throw error;
        }
    }
    
    async checkDelegationStatus() {
        try {
            if (!this.playerAccount) {
                this.isDelegated = false;
                return false;
            }
            
            const accountInfo = await this.l1Connection.getAccountInfo(this.playerAccount);
            
            if (!accountInfo) {
                this.isDelegated = false;
                return false;
            }
            
            const DELEGATION_PROGRAM = 'DELeGGvXpWV2fqJUhqcF5ZSYMS4JTLjteaAMARRSaeSh';
            const isDelegated = accountInfo.owner.toString() === DELEGATION_PROGRAM;
            
            this.isDelegated = isDelegated;
            return this.isDelegated;
        } catch (error) {
            console.error('Error checking delegation:', error);
            this.isDelegated = false;
            return false;
        }
    }
    
    async ensureGameStateInitialized() {
        try {
            const accountInfo = await this.provider.connection.getAccountInfo(this.gameStateAccount);
            
            if (!accountInfo) {
                await this.initializeGameState();
            }
        } catch (error) {
            console.error('Error ensuring game state:', error);
            throw error;
        }
    }

    async initializeGameState() {
            try {
                const tx = await this.program.methods
                .initializeGameState()
                .accounts({
                        gameState: this.gameStateAccount,
                        authority: this.wallet.publicKey,
                        systemProgram: SystemProgram.programId
                })
                .rpc();
                
                return tx;
        } catch (error) {
            console.error('Error initializing game state:', error);
            throw error;
        }
    }

    async registerPlayer(username) {
        try {
        await this.ensureGameStateInitialized();
        
        const [usernameRegistryAccount] = PublicKey.findProgramAddressSync(
                [Buffer.from('username'), Buffer.from(username)],
                this.program.programId
        );
        
            const tx = await this.program.methods
                .registerPlayer(username)
                .accounts({
                    player: this.playerAccount,
                    usernameRegistry: usernameRegistryAccount,
                    authority: this.wallet.publicKey,
                    systemProgram: SystemProgram.programId
                })
                .rpc();
            
            return tx;
        } catch (error) {
            if (error.message && error.message.includes('already in use')) {
                throw new Error('Username already taken');
            }
            console.error('Error registering player:', error);
            throw error;
        }
    }
    
    async submitScore(score) {
        try {
            const scoreBN = new BN(Number(score) || 0, 10);
            const programToUse = this.isDelegated ? this.erProgram : this.l1Program;
            
            const tx = await programToUse.methods
                .submitScore(scoreBN)
                .accounts({
                    player: this.playerAccount,
                    authority: this.wallet.publicKey
                })
                .rpc();
            
            return tx;
        } catch (error) {
            console.error('Error submitting score:', error);
            throw error;
        }
    }

    async getPlayerData() {
        try {
            const programToUse = this.isDelegated ? this.erProgram : this.l1Program;
            const playerData = await programToUse.account.player.fetch(this.playerAccount);
            return playerData;
        } catch (error) {
            return null;
        }
    }

    async getGameHistory() {
        try {
            const playerData = await this.getPlayerData();
            
            if (playerData && playerData.gameHistory) {
                    return playerData.gameHistory.map(game => ({
                        score: game.score ? game.score.toNumber() : game.score,
                        timestamp: game.timestamp ? game.timestamp.toNumber() : game.timestamp,
                        date: new Date((game.timestamp ? game.timestamp.toNumber() : game.timestamp) * 1000).toLocaleString('ru-RU')
                    }));
            }
            return [];
        } catch (error) {
            console.error('Error getting game history:', error);
            return [];
        }
    }

    async getLeaderboard() {
        try {
            let players = [];
            
            try {
                const allPlayers = await this.erProgram.account.player.all();
                
                players = allPlayers.map(account => ({
                    name: account.account.username || 'Unknown',
                    gamesPlayed: account.account.gamesPlayed ? account.account.gamesPlayed.toNumber() : 0,
                    bestScore: account.account.bestScore ? account.account.bestScore.toNumber() : 0,
                    bestScoreTimestamp: account.account.bestScoreTimestamp ? account.account.bestScoreTimestamp.toNumber() : 0,
                    authority: account.account.authority ? account.account.authority.toString() : 'Unknown'
                })).filter(player => player !== null);
                
                players.sort((a, b) => b.bestScore - a.bestScore);
            } catch (error) {
                const currentPlayer = await this.getPlayerData();
                if (currentPlayer) {
                    players = [{
                        name: currentPlayer.username,
                        gamesPlayed: currentPlayer.gamesPlayed ? currentPlayer.gamesPlayed.toNumber() : 0,
                        bestScore: currentPlayer.bestScore ? currentPlayer.bestScore.toNumber() : 0,
                        authority: this.wallet.publicKey.toString()
                    }];
                }
            }
            
            return {
                totalPlayers: players.length,
                totalGames: players.reduce((sum, p) => sum + p.gamesPlayed, 0),
                players: players
            };
        } catch (error) {
            console.error('Error getting leaderboard:', error);
            return { 
                totalPlayers: 0, 
                totalGames: 0, 
                players: [] 
            };
        }
    }
    
    async delegatePlayerAccount() {
        try {
            const tx = await this.l1Program.methods
                .delegatePlayer()
                .accounts({
                    payer: this.wallet.publicKey,
                    player: this.playerAccount,
                })
                .rpc();
            
            this.isDelegated = true;
            return tx;
        } catch (error) {
            console.error('Delegation failed:', error);
            
            if (error.message && error.message.includes('already')) {
                this.isDelegated = true;
                return 'already_delegated';
            }
            
            throw error;
        }
    }
    
    async delegateGameState() {
        try {
            const tx = await this.l1Program.methods
                .delegateGameState()
                .accounts({
                    payer: this.wallet.publicKey,
                    gameState: this.gameStateAccount,
                })
                .rpc();
            
            return tx;
        } catch (error) {
            console.error('GameState delegation failed:', error);
            
            if (error.message && error.message.includes('already')) {
                return 'already_delegated';
            }
            
            throw error;
        }
    }
    
    async undelegatePlayer() {
        try {
            const tx = await this.l1Program.methods
                .undelegatePlayer()
                .accounts({
                    payer: this.wallet.publicKey,
                    player: this.playerAccount,
                })
                .rpc();
            
            this.isDelegated = false;
            return tx;
        } catch (error) {
            console.error('Undelegation failed:', error);
            throw error;
        }
    }
    
    async enableFastMode() {
        try {
            const playerData = await this.getPlayerData();
            
            if (!playerData) {
                return false;
            }
            
            if (this.isDelegated) {
                return true;
            }
            
            await this.delegatePlayerAccount();
            
            return true;
        } catch (error) {
            console.error('Could not enable Fast Mode:', error);
            return false;
        }
    }
    
    getInfo() {
        return {
            connected: this.isConnected,
            delegated: this.isDelegated,
            wallet: this.wallet?.publicKey?.toString() || 'Not connected',
            player: this.playerAccount?.toString() || 'Not initialized',
            l1Endpoint: this.l1Connection?.rpcEndpoint || 'Not connected',
            erEndpoint: this.erConnection?.rpcEndpoint || 'Not connected',
            mode: this.isDelegated ? '⚡ Fast Mode (ER)' : '📍 Standard Mode (L1)',
            message: this.isDelegated 
                ? 'Transactions are INSTANT via Ephemeral Rollups!' 
                : 'Connect and delegate for instant transactions'
        };
    }
}

export default BlockchainManager;
